package local.tvmorph.tv;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.widget.*;
import org.json.*;import java.util.*;import java.util.concurrent.*;
/** Shared player controls with a permission-scoped local queue. */
public final class UsbPlayerActivity extends PlayerActivity {
 private static final int FOLDER=674,FILES=675,SUBTITLE=676;
 private JSONArray queue=new JSONArray();private int index;private final ExecutorService files=Executors.newSingleThreadExecutor();
 private String text(String ar,String en){return UiSettings.text(this,ar,en);}
 @Override protected boolean localMedia(){return true;}
 private Intent itemIntent(int position)throws Exception{JSONObject row=queue.getJSONObject(position);Uri uri=Uri.parse(row.getString("uri"));String hash=java.util.Base64.getUrlEncoder().withoutPadding().encodeToString(java.security.MessageDigest.getInstance("SHA-256").digest(uri.toString().getBytes("UTF-8")));Intent intent=new Intent(this,UsbPlayerActivity.class).setData(uri).putExtra("url",uri.toString()).putExtra("name",row.getString("name")).putExtra("mime",row.getString("mime")).putExtra("itemKind","local").putExtra("itemId",hash).putExtra("resumeKey",PlaybackMemory.key(PlaybackMemory.account(this,"usb"),"local",hash)).putExtra("queue",queue.toString()).putExtra("queueIndex",position).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);intent.setClipData(LocalMediaQueue.grants(queue));return intent;}
 @Override public void onCreate(Bundle state){try{String saved=state!=null?state.getString("localQueue"):getIntent().getStringExtra("queue");queue=LocalMediaQueue.clean(saved==null?null:new JSONArray(saved));if(queue.length()==0){Uri uri=getIntent().getData();if(uri!=null){JSONObject row=LocalMediaQueue.row(this,uri);if(row!=null)queue.put(row);}}if(queue.length()==0){super.onCreate(state);finish();return;}index=Math.max(0,Math.min(queue.length()-1,state!=null?state.getInt("localIndex"):getIntent().getIntExtra("queueIndex",0)));setIntent(itemIntent(index));}catch(Exception error){super.onCreate(state);finish();return;}super.onCreate(state);adjacentAvailable(index>0,index+1<queue.length());}
 @Override protected void adjacent(int delta){int next=index+delta;if(next<0||next>=queue.length()){Toast.makeText(this,text(delta<0?"ده أول فيديو في القائمة.":"ده آخر فيديو في القائمة.",delta<0?"This is the first video in the queue.":"This is the last video in the queue."),0).show();return;}try{if(replacePlayback(itemIntent(next))){index=next;adjacentAvailable(index>0,index+1<queue.length());}}catch(Exception error){Toast.makeText(this,text("تعذّر فتح الفيديو.","Could not open video."),1).show();}}
 @Override protected void localFiles(){String[] names=new String[queue.length()];for(int i=0;i<names.length;i++)names[i]=queue.optJSONObject(i).optString("name");new AlertDialog.Builder(this).setTitle(text("قائمة الفيديوهات","Video queue")).setSingleChoiceItems(names,index,(dialog,which)->{dialog.dismiss();if(which!=index)adjacent(which-index);}).setPositiveButton(text("فتح مجلد","Open folder"),(d,w)->pick(FOLDER)).setNeutralButton(text("اختيار ملفات","Choose files"),(d,w)->pick(FILES)).setNegativeButton(text("إغلاق","Close"),null).show();}
 private void pick(int request){Intent intent=request==FOLDER?new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE):new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(request==SUBTITLE?"*/*":"video/*");intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);if(request==FILES)intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);try{startActivityForResult(intent,request);}catch(ActivityNotFoundException error){Toast.makeText(this,text("النظام لا يوفر متصفح ملفات متوافق.","This device has no compatible system file picker."),1).show();}}
 @Override protected void pickSubtitle(){pick(SUBTITLE);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||!Arrays.asList(FOLDER,FILES,SUBTITLE).contains(request))return;final Uri selected=data.getData();final String current=getIntent().getData().toString();files.execute(()->{try{if(request==SUBTITLE){if(selected==null)return;String name=String.valueOf(LocalMediaQueue.name(this,selected)).toLowerCase(Locale.ROOT),mime=name.endsWith(".srt")?"application/x-subrip":name.endsWith(".vtt")?"text/vtt":name.endsWith(".ass")||name.endsWith(".ssa")?"text/x-ssa":null;if(mime==null)throw new IllegalArgumentException();runOnUiThread(()->{if(!isFinishing()&&!isDestroyed()&&current.equals(getIntent().getData().toString()))attachSubtitle(selected,mime);});return;}List<Uri> selection=new ArrayList<>();if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount()&&i<LocalMediaQueue.LIMIT;i++)selection.add(data.getClipData().getItemAt(i).getUri());if(selected!=null)selection.add(selected);JSONArray next=request==FOLDER?LocalMediaQueue.folder(this,selected):LocalMediaQueue.selected(this,selection);if(next.length()==0)throw new IllegalArgumentException();runOnUiThread(()->{if(isFinishing()||isDestroyed())return;try{queue=next;int target=0;for(int i=0;i<queue.length();i++)if(current.equals(queue.getJSONObject(i).getString("uri")))target=i;index=target;ClipData clip=data.getClipData();if(clip==null&&selected!=null)clip=ClipData.newRawUri("Selected media",selected);if(clip!=null)getIntent().setClipData(clip);replacePlayback(itemIntent(index));adjacentAvailable(index>0,index+1<queue.length());}catch(Exception ignored){}});}catch(Exception error){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())Toast.makeText(this,text(request==SUBTITLE?"اختر ملف ترجمة SRT أو VTT أو ASS صالحًا.":"تعذّر قراءة فيديوهات الاختيار. اختار ملفًا أو مجلدًا مسموحًا للتطبيق.",request==SUBTITLE?"Choose a valid SRT, VTT or ASS subtitle file.":"Could not read the selected videos. Choose an accessible file or folder."),1).show();});}});}
 @Override protected void onSaveInstanceState(Bundle state){state.putString("localQueue",queue.toString());state.putInt("localIndex",index);super.onSaveInstanceState(state);}
 @Override protected void onDestroy(){files.shutdownNow();super.onDestroy();}
}
